<script>
(function () {
  function getHostWin() {
    try {
      if (window.parent && window.parent !== window && window.parent.document) {
        return window.parent;
      }
    } catch (e) {}
    return window;
  }

  function getHostDoc() {
    const hw = getHostWin();
    return hw && hw.document ? hw.document : document;
  }

  function syncHostTheme() {
    try {
      const hw = getHostWin();
      const hd = hw.document;
      if (hd === document) return;
      const rootStyle = hw.getComputedStyle(hd.documentElement);
      const bodyStyle = hd.body ? hw.getComputedStyle(hd.body) : rootStyle;
      ["--SmartThemeBodyColor", "--SmartThemeEmColor", "--SmartThemeBorderColor", "--mainFontFamily"].forEach(function (name) {
        const val = bodyStyle.getPropertyValue(name).trim() || rootStyle.getPropertyValue(name).trim();
        if (val) document.documentElement.style.setProperty(name, val);
      });
      if (!bodyStyle.getPropertyValue("--SmartThemeBodyColor").trim() && !rootStyle.getPropertyValue("--SmartThemeBodyColor").trim() && bodyStyle.color) {
        document.documentElement.style.setProperty("--SmartThemeBodyColor", bodyStyle.color);
      }
      if (!bodyStyle.getPropertyValue("--mainFontFamily").trim() && !rootStyle.getPropertyValue("--mainFontFamily").trim() && bodyStyle.fontFamily) {
        document.documentElement.style.setProperty("--mainFontFamily", bodyStyle.fontFamily);
      }
    } catch (e) {}
  }

  const cardEl = document.getElementById("yd-talk-card");
  const rawEl = document.getElementById("yd-talk-raw");
  const listEl = document.getElementById("yd-floor-list");
  const countEl = document.getElementById("yd-talk-count");
  const previewEl = document.getElementById("yd-talk-preview");
  const collapseBtn = document.getElementById("yd-collapse-btn");
  const replyInput = document.getElementById("yd-reply-input");
  const replyRoleSelect = document.getElementById("yd-reply-role");
  const replyBtn = document.getElementById("yd-reply-btn");
  const toastEl = document.getElementById("yd-talk-toast");

  function notifyFrameResize() {
    try {
      if (window.frameElement && window.parent && window.parent !== window) {
        const target = cardEl || document.body;
        const h = target ? Math.ceil(target.getBoundingClientRect().height) + 8 : document.documentElement.scrollHeight;
        window.frameElement.style.height = Math.max(h, 36) + "px";
      }
    } catch (e) {}
  }

  syncHostTheme();
  try {
    const hd = getHostDoc();
    if (hd !== document && typeof MutationObserver !== "undefined" && hd.body) {
      new MutationObserver(syncHostTheme).observe(hd.body, { attributes: true, attributeFilter: ["data-theme", "class", "style"] });
      new MutationObserver(syncHostTheme).observe(hd.documentElement, { attributes: true, attributeFilter: ["data-theme", "class", "style"] });
    }
  } catch (e) {}

  let toastTimer = null;
  function showToast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    notifyFrameResize();
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
      notifyFrameResize();
    }, 2600);
  }

  let initialRaw = "";
  if (rawEl) {
    initialRaw = typeof rawEl.value === "string" ? rawEl.value : (rawEl.textContent || "");
    if (/<(?:br|\/(?:p|div|li))>/i.test(initialRaw)) {
      const norm = initialRaw.replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|div|li)>/gi, "\n");
      const tmp = document.createElement("div");
      tmp.innerHTML = norm;
      initialRaw = tmp.textContent || "";
    }
  }

  let currentBlockText = initialRaw.trim();
  let editingFloorIdx = -1;
  let isWriting = false;

  function parseFloors(blockText) {
    const lines = blockText.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(Boolean);
    const floors = [];
    const lineRe = /^※\s*([^：\r\n:]{1,24})[：:]\s*(.*)$/;
    lines.forEach(function (line) {
      const m = line.match(lineRe);
      if (m) {
        floors.push({ speaker: m[1].trim(), text: m[2].trim() });
      } else if (floors.length > 0) {
        floors[floors.length - 1].text += "\n" + line;
      } else {
        floors.push({ speaker: "随记", text: line.replace(/^※\s*/, "") });
      }
    });
    return floors;
  }

  function serializeFloors(floors) {
    return floors.map(function (f) {
      const cleanBody = String(f.text || "").replace(/\r?\n+/g, " ").trim();
      return "※ " + f.speaker + "：" + cleanBody;
    }).join("\n");
  }

  function getRoleMeta(speaker) {
    const s = speaker.trim();
    const low = s.toLowerCase();
    if (s === "莉莉丝" || low === "lilith" || s === "泠音" || low === "lingyin") {
      return { cls: "is-author", badge: "作者", avatar: s.charAt(0).toUpperCase() };
    }
    if (s === "随记" || s === "伏笔") {
      return { cls: "is-author", badge: "伏笔", avatar: s.charAt(0) };
    }
    if (low === "master" || s === "读者") {
      return { cls: "is-master", badge: "读者", avatar: low === "master" ? "M" : s.charAt(0) };
    }
    return { cls: "is-guest", badge: "客评", avatar: (s.charAt(0) || "?").toUpperCase() };
  }

  function resolveTavernAdapter() {
    const hw = getHostWin();
    const th = window.TavernHelper || (hw && hw.TavernHelper) || null;
    const getChatMessages = window.getChatMessages || (th && th.getChatMessages) || (hw && hw.getChatMessages) || null;
    const setChatMessages = window.setChatMessages || (th && th.setChatMessages) || (hw && hw.setChatMessages) || null;
    const getCurrentMessageId = window.getCurrentMessageId || (th && th.getCurrentMessageId) || (hw && hw.getCurrentMessageId) || null;
    if (!getChatMessages || !setChatMessages) return null;
    return { getChatMessages: getChatMessages, setChatMessages: setChatMessages, getCurrentMessageId: getCurrentMessageId };
  }

  function detectMessageContext() {
    let mesId = null;
    let blockIdx = 0;
    const adapter = resolveTavernAdapter();
    try {
      if (adapter && adapter.getCurrentMessageId) {
        const cid = adapter.getCurrentMessageId();
        if (typeof cid === "number" && cid >= 0) mesId = cid;
        else if (typeof cid === "string" && /^\d+$/.test(cid)) mesId = Number(cid);
      }
    } catch (e) {}

    try {
      if (window.frameElement) {
        const mesEl = window.frameElement.closest("[mesid]");
        if (mesEl) {
          if (mesId === null) {
            const rawAttr = mesEl.getAttribute("mesid");
            if (rawAttr !== null && /^\d+$/.test(rawAttr)) mesId = Number(rawAttr);
          }
          const frames = Array.prototype.slice.call(mesEl.querySelectorAll("iframe"));
          let commentCount = 0;
          for (let i = 0; i < frames.length; i++) {
            const fr = frames[i];
            if (fr === window.frameElement) {
              blockIdx = commentCount;
              break;
            }
            try {
              if (fr.contentDocument && fr.contentDocument.querySelector('[data-yd-card="comment"]')) {
                commentCount++;
              }
            } catch (e) {}
          }
        }
      }
    } catch (e) {}

    return { mesId: mesId, blockIdx: blockIdx, adapter: adapter };
  }

  function maskThinkBlocks(text) {
    return text.replace(/<构思(?=[\s>])[^>]*>[\s\S]*?<\/构思>/gi, function (m) {
      return m.replace(/[^\r\n]/g, " ");
    });
  }

  function findCommentBlocksInMessage(msgText) {
    const masked = maskThinkBlocks(msgText);
    const re = /(?:^|\n)([ \t]*※[ \t]*[^：\r\n:]{1,24}[：:][^\r\n]*(?:\r?\n[ \t]*※[ \t]*[^：\r\n:]{1,24}[：:][^\r\n]*)*)(?=[ \t]*(?:\r?\n|$))/g;
    const ranges = [];
    let match;
    while ((match = re.exec(masked)) !== null) {
      const fullStart = match.index + (match[0].startsWith("\n") ? 1 : 0);
      const blockStr = match[1];
      ranges.push({ start: fullStart, end: fullStart + blockStr.length, raw: msgText.slice(fullStart, fullStart + blockStr.length) });
    }
    return ranges;
  }

  async function persistBlockUpdate(nextBlockText, okMsg, onSuccess) {
    if (isWriting) return false;
    isWriting = true;
    if (replyBtn) replyBtn.disabled = true;
    if (replyInput) replyInput.disabled = true;

    try {
      const ctx = detectMessageContext();
      if (!ctx.adapter || ctx.mesId === null) {
        currentBlockText = nextBlockText;
        editingFloorIdx = -1;
        if (onSuccess) onSuccess();
        render();
        showToast(okMsg + "（离线沙盒模式：仅本地暂存）");
        return true;
      }

      const list = await ctx.adapter.getChatMessages(ctx.mesId);
      const msgObj = Array.isArray(list) ? list[0] : null;
      if (!msgObj || typeof msgObj.message !== "string") {
        throw new Error("未读取到当前消息正文");
      }

      const ranges = findCommentBlocksInMessage(msgObj.message);
      let targetRange = ranges[ctx.blockIdx] || null;
      if (!targetRange || targetRange.raw.trim() !== currentBlockText.trim()) {
        const exact = ranges.find(function (r) { return r.raw.trim() === currentBlockText.trim(); });
        if (exact) targetRange = exact;
      }
      if (!targetRange) {
        throw new Error("未能定位当前批注串在消息中的位置");
      }

      const before = msgObj.message.slice(0, targetRange.start);
      const after = msgObj.message.slice(targetRange.end);
      let updatedMsg = before + nextBlockText + after;
      if (!nextBlockText) {
        updatedMsg = before.replace(/\n{2,}$/, "\n") + after.replace(/^\n{2,}/, "\n");
      }

      await ctx.adapter.setChatMessages([{ message_id: ctx.mesId, message: updatedMsg }], { refresh: "none" });
      currentBlockText = nextBlockText;
      editingFloorIdx = -1;
      if (onSuccess) onSuccess();
      render();
      showToast(okMsg);
      return true;
    } catch (err) {
      showToast("⚠️ 写回失败：" + (err && err.message ? err.message : String(err)));
      return false;
    } finally {
      isWriting = false;
      if (replyBtn) replyBtn.disabled = false;
      if (replyInput) replyInput.disabled = false;
    }
  }

  function render() {
    const floors = parseFloors(currentBlockText);
    if (countEl) countEl.textContent = floors.length + " 楼";
    if (previewEl) {
      previewEl.textContent = floors.length ? (floors[0].speaker + "：" + floors[0].text) : "";
    }

    listEl.innerHTML = "";
    floors.forEach(function (floor, idx) {
      const roleMeta = getRoleMeta(floor.speaker);

      const row = document.createElement("div");
      row.className = "yd-floor " + roleMeta.cls;

      const meta = document.createElement("div");
      meta.className = "yd-floor-meta";

      const avatar = document.createElement("span");
      avatar.className = "yd-avatar";
      avatar.textContent = roleMeta.avatar;
      meta.appendChild(avatar);

      const speaker = document.createElement("span");
      speaker.className = "yd-speaker";
      speaker.textContent = floor.speaker;
      meta.appendChild(speaker);

      const badge = document.createElement("span");
      badge.className = "yd-badge";
      badge.textContent = roleMeta.badge;
      meta.appendChild(badge);

      const num = document.createElement("span");
      num.className = "yd-floor-num";
      num.textContent = "#" + (idx + 1);
      meta.appendChild(num);

      const actions = document.createElement("div");
      actions.className = "yd-floor-actions";

      const editBtn = document.createElement("button");
      editBtn.type = "button";
      editBtn.className = "yd-mini-btn";
      editBtn.textContent = "编辑";
      editBtn.addEventListener("click", function () {
        editingFloorIdx = editingFloorIdx === idx ? -1 : idx;
        render();
      });
      actions.appendChild(editBtn);

      const delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "yd-mini-btn is-danger";
      delBtn.textContent = "删除";
      delBtn.addEventListener("click", function () {
        const nextFloors = floors.filter(function (_, j) { return j !== idx; });
        persistBlockUpdate(serializeFloors(nextFloors), "🗑️ 已删除该条记录");
      });
      actions.appendChild(delBtn);

      meta.appendChild(actions);

      row.appendChild(meta);

      if (editingFloorIdx === idx) {
        const editBox = document.createElement("div");
        editBox.className = "yd-edit-box";

        const editInput = document.createElement("textarea");
        editInput.className = "yd-edit-input";
        editInput.value = floor.text;
        editBox.appendChild(editInput);

        const editBar = document.createElement("div");
        editBar.className = "yd-edit-bar";

        const saveBtn = document.createElement("button");
        saveBtn.type = "button";
        saveBtn.className = "yd-mini-btn";
        saveBtn.textContent = "保存";
        saveBtn.addEventListener("click", function () {
          const val = editInput.value.trim();
          if (!val) {
            showToast("⚠️ 点评内容不能为空，如需移除请点删除");
            return;
          }
          const nextFloors = floors.map(function (item, j) {
            return j === idx ? { speaker: item.speaker, text: val } : item;
          });
          persistBlockUpdate(serializeFloors(nextFloors), "✅ 已保存修改");
        });
        editBar.appendChild(saveBtn);

        const cancelBtn = document.createElement("button");
        cancelBtn.type = "button";
        cancelBtn.className = "yd-mini-btn";
        cancelBtn.textContent = "取消";
        cancelBtn.addEventListener("click", function () {
          editingFloorIdx = -1;
          render();
        });
        editBar.appendChild(cancelBtn);

        editBox.appendChild(editBar);
        row.appendChild(editBox);
      } else {
        const textEl = document.createElement("div");
        textEl.className = "yd-floor-text";
        textEl.textContent = floor.text;
        row.appendChild(textEl);
      }

      listEl.appendChild(row);
    });

    notifyFrameResize();
  }

  function handleAppend() {
    const val = replyInput ? replyInput.value.replace(/\r?\n+/g, " ").trim() : "";
    if (!val) {
      showToast("⚠️ 请输入内容后再追加");
      return;
    }
    const speakerTag = replyRoleSelect && replyRoleSelect.value ? replyRoleSelect.value : "master";
    const floors = parseFloors(currentBlockText);
    floors.push({ speaker: speakerTag, text: val });
    persistBlockUpdate(serializeFloors(floors), "💬 已追加 " + speakerTag + " 记录", function () {
      if (replyInput) replyInput.value = "";
    });
  }

  if (replyBtn) {
    replyBtn.addEventListener("click", handleAppend);
  }
  if (replyInput) {
    replyInput.addEventListener("keydown", function (e) {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleAppend();
      }
    });
  }

  if (collapseBtn && cardEl) {
    collapseBtn.addEventListener("click", function () {
      const collapsed = cardEl.classList.toggle("is-collapsed");
      collapseBtn.textContent = collapsed ? "▸" : "▾";
      collapseBtn.setAttribute("aria-expanded", String(!collapsed));
      notifyFrameResize();
    });
  }

  render();

  if (typeof ResizeObserver !== "undefined" && (cardEl || document.body)) {
    new ResizeObserver(notifyFrameResize).observe(cardEl || document.body);
  }
})();
</script>
</body>
</html>
