(function () {
  function getHostDoc() {
    try {
      if (window.parent && window.parent !== window && window.parent.document) {
        return window.parent.document;
      }
    } catch (e) {}
    return document;
  }

  function syncHostTheme() {
    try {
      const hostDoc = getHostDoc();
      if (hostDoc === document) return;
      const rootStyle = window.parent.getComputedStyle(hostDoc.documentElement);
      const bodyStyle = hostDoc.body ? window.parent.getComputedStyle(hostDoc.body) : rootStyle;
      ["--SmartThemeBodyColor", "--SmartThemeEmColor", "--SmartThemeBorderColor", "--mainFontFamily"].forEach(function (name) {
        const val = bodyStyle.getPropertyValue(name).trim() || rootStyle.getPropertyValue(name).trim();
        if (val) document.documentElement.style.setProperty(name, val);
      });
      if (!bodyStyle.getPropertyValue("--SmartThemeBodyColor").trim() && !rootStyle.getPropertyValue("--SmartThemeBodyColor").trim() && bodyStyle.color) {
        document.documentElement.style.setProperty("--SmartThemeBodyColor", bodyStyle.color);
      }
      if (!bodyStyle.getPropertyValue("--mainFontFamily").trim() && !rootStyle.getPropertyValue("--mainFontFamily").trim() && bodyStyle.fontFamily) {
        document.documentElement.style.setProperty("--mainFontFamily", bodyStyle.fontFamily);
      }
    } catch (e) {}
  }

  const cardEl = document.getElementById("yd-opt-card");
  const rawEl = document.getElementById("yd-opt-raw");
  const listEl = document.getElementById("yd-opt-list");
  const countEl = document.getElementById("yd-opt-count");
  const fallbackEl = document.getElementById("yd-opt-fallback");
  const toastEl = document.getElementById("yd-opt-toast");
  const collapseBtn = document.getElementById("yd-collapse-btn");

  function notifyFrameResize() {
    try {
      if (window.frameElement && window.parent && window.parent !== window) {
        const target = cardEl || document.body;
        const h = target ? Math.ceil(target.getBoundingClientRect().height) + 8 : document.documentElement.scrollHeight;
        window.frameElement.style.height = Math.max(h, 36) + "px";
      }
    } catch (e) {}
  }

  syncHostTheme();
  try {
    const hostDoc = getHostDoc();
    if (hostDoc !== document && typeof MutationObserver !== "undefined" && hostDoc.body) {
      new MutationObserver(syncHostTheme).observe(hostDoc.body, { attributes: true, attributeFilter: ["data-theme", "class", "style"] });
      new MutationObserver(syncHostTheme).observe(hostDoc.documentElement, { attributes: true, attributeFilter: ["data-theme", "class", "style"] });
    }
  } catch (e) {}

  let mode = "fill";
  let toastTimer = null;

  function showToast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    notifyFrameResize();
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
      notifyFrameResize();
    }, 2400);
  }

  document.querySelectorAll(".yd-mode-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      document.querySelectorAll(".yd-mode-btn").forEach(function (b) { b.classList.remove("active"); });
      btn.classList.add("active");
      mode = btn.getAttribute("data-mode") || "fill";
    });
  });

  if (collapseBtn && cardEl) {
    collapseBtn.addEventListener("click", function () {
      const collapsed = cardEl.classList.toggle("is-collapsed");
      collapseBtn.textContent = collapsed ? "▸" : "▾";
      collapseBtn.setAttribute("aria-expanded", String(!collapsed));
      notifyFrameResize();
    });
  }

  let rawText = "";
  if (rawEl) {
    rawText = typeof rawEl.value === "string" ? rawEl.value : (rawEl.textContent || "");
    if (/<(?:br|\/(?:p|div|li))>/i.test(rawText)) {
      const normalized = rawText.replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|div|li)>/gi, "\n");
      const tmp = document.createElement("div");
      tmp.innerHTML = normalized;
      rawText = tmp.textContent || "";
    }
  }
  rawText = rawText.trim();

  function parseOptionLines(text) {
    if (!text) return [];
    const rawLines = text.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(Boolean);
    const items = [];
    const prefixRe = /^(?:([A-Za-z0-9]+)\s*[.、:：)\]]|[-*•·])\s*(.+)$/;
    const titleRe = /^(?:\[([^\]\n]+)\]|【([^】\n]+)】)\s*[：:.\-—]*\s*(.*)$/;
    const colonTitleRe = /^([^：:\n，。！？“"‘']{1,12})[：:]\s*(.+)$/;

    rawLines.forEach(function (line) {
      const pm = line.match(prefixRe);
      if (pm || items.length === 0) {
        const badge = pm && pm[1] ? pm[1].toUpperCase() : String.fromCharCode(65 + items.length);
        const body = pm ? pm[2].trim() : line;
        let title = "";
        let desc = body;
        const tm = body.match(titleRe);
        if (tm) {
          title = (tm[1] || tm[2] || "").trim();
          desc = (tm[3] || "").trim();
        } else {
          const cm = body.match(colonTitleRe);
          if (cm && !/^[“"‘']/.test(cm[1].trim())) {
            title = cm[1].trim();
            desc = cm[2].trim();
          }
        }
        items.push({ badge: badge, title: title, desc: desc || title || body });
      } else {
        items[items.length - 1].desc += "\n" + line;
      }
    });
    return items;
  }

  const parsedItems = parseOptionLines(rawText);
  if (countEl) {
    countEl.textContent = parsedItems.length ? parsedItems.length + " 项" : "原文";
  }

  if (parsedItems.length > 0) {
    parsedItems.forEach(function (item) {
      const fillText = item.desc || item.title;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "yd-opt-item";

      const topRow = document.createElement("div");
      topRow.className = "yd-opt-item-top";

      const badgeEl = document.createElement("span");
      badgeEl.className = "yd-opt-badge";
      badgeEl.textContent = item.badge;
      topRow.appendChild(badgeEl);

      if (item.title) {
        const labelEl = document.createElement("span");
        labelEl.className = "yd-opt-label";
        labelEl.textContent = item.title;
        topRow.appendChild(labelEl);
      }

      const descEl = document.createElement("div");
      descEl.className = "yd-opt-desc";
      descEl.textContent = item.desc;

      btn.appendChild(topRow);
      btn.appendChild(descEl);

      btn.addEventListener("click", function () {
        document.querySelectorAll(".yd-opt-item.is-picked").forEach(function (el) { el.classList.remove("is-picked"); });
        btn.classList.add("is-picked");

        const hostDoc = getHostDoc();
        const ta = hostDoc.querySelector("#send_textarea") || document.querySelector("#send_textarea");
        const sendBtn = hostDoc.querySelector("#send_but") || document.querySelector("#send_but");

        if (ta) {
          ta.value = fillText;
          ta.dispatchEvent(new Event("input", { bubbles: true }));
          ta.dispatchEvent(new Event("change", { bubbles: true }));
          ta.focus();
          if (mode === "send" && sendBtn) {
            sendBtn.click();
          }
          showToast((mode === "send" ? "🚀 已发送：" : "📝 已填入输入框：") + fillText);
        } else if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(fillText).then(function () {
            showToast("📋 已复制建议内容：" + fillText);
          }).catch(function () {
            showToast("⚠️ 未找到酒馆输入框，请长按复制文本");
          });
        } else {
          showToast("⚠️ 未找到酒馆输入框，请手动复制文本");
        }
      });

      listEl.appendChild(btn);
    });
  } else if (fallbackEl) {
    fallbackEl.textContent = rawText || "（未识别到可用选项内容）";
    fallbackEl.style.display = "block";
  }

  if (typeof ResizeObserver !== "undefined" && (cardEl || document.body)) {
    new ResizeObserver(notifyFrameResize).observe(cardEl || document.body);
  }
  notifyFrameResize();
})();
</script>
